import http.client
import json
import os


def main():
    stage = "configuration"
    status = None
    connection = None
    result = None
    try:
        api_key = os.environ.get("RESEND_API_KEY")
        subject = os.environ.get("FIRSTCALL_SUBJECT")
        if not api_key or not subject:
            result = {
                "ok": False,
                "stage": stage,
                "error_type": "MissingEnvironmentVariable",
                "http_status": None,
            }
        else:
            payload = json.dumps({
                "from": "FIRSTCALL <onboarding@resend.dev>",
                "to": ["delivered@resend.dev"],
                "subject": subject,
                "html": "<strong>It works</strong>",
            }).encode("utf-8")
            stage = "request"
            connection = http.client.HTTPSConnection("api.resend.com", timeout=30)
            connection.request(
                "POST",
                "/emails",
                body=payload,
                headers={
                    "Authorization": "Bearer " + api_key,
                    "Content-Type": "application/json",
                },
            )
            response = connection.getresponse()
            status = response.status
            stage = "response"
            if not 200 <= status < 300:
                result = {
                    "ok": False,
                    "stage": stage,
                    "error_type": "HTTPError",
                    "http_status": status,
                }
            else:
                data = json.loads(response.read())
                if isinstance(data, dict) and isinstance(data.get("id"), str) and data["id"].strip():
                    result = {"ok": True, "stage": "complete"}
                else:
                    result = {
                        "ok": False,
                        "stage": stage,
                        "error_type": "InvalidResponse",
                        "http_status": status,
                    }
    except Exception:
        result = {
            "ok": False,
            "stage": stage,
            "error_type": "IntegrationError",
            "http_status": status,
        }
    finally:
        if connection is not None:
            try:
                connection.close()
            except Exception:
                pass
    print("FIRSTCALL_RESULT " + json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()
